window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cb6553d7bc46b6e0"]={"versions": [{"id": "FIG-cb6553d7bc46b6e0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Zustandsautomat (<code>sm Buffer lock</code>) mit zwei orthogonalen, nebenläufigen Zustandsräumen (<em>Transmit Buffer</em> und <em>Receiving Buffer</em>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Schicht der Kommunikations-Dienste (<em>Communication Services</em>), Modul <strong>CanTp</strong> (CAN Transport Layer, ISO 15765-2) im Zusammenspiel mit dem <strong>PduR</strong> (PDU Router) und den oberen Schichten (DCM, COM).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Definition des Puffer-Lebenszyklus und der Puffer-Sperrsemantik (<em>Buffer Locking</em>) in den übergeordneten Modulen während segmentierter sowie unsegmentierter N-SDU-Übertragungen (Tx) und -Empfangsvorgänge (Rx), um Dateninkonsistenzen (Race Conditions, Buffer Overwrites) bei asynchroner Datenbereitstellung zu verhindern.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>CanTp:</strong> Treiber-/Transportinstanz, die Daten segmentiert/desegmentiert und die Callbacks der oberen Schicht triggert.\n</li><li><strong>PduR / Upper Layer (DCM / COM):</strong> Eigentümer der N-SDU-Puffer (<code>Transmit Buffer</code>, <code>Receiving Buffer</code>).\n</li></ul>\n</li><li><strong>Zustände (je Pufferinstanz):</strong>\n<ul class=\"fig-list\"><li><code>UNLOCK</code>: Puffer steht der übergeordneten Schicht zur freien Modifikation, Freigabe oder Neuzuweisung bereit.\n</li><li><code>LOCK</code>: Puffer ist für die Transportübertragung exklusiv an CanTp gebunden; Modifikationen durch die Applikation/obere Schicht sind unzulässig.\n</li></ul>\n</li><li><strong>Schnittstellen / API-Signaturen:</strong>\n<ul class=\"fig-list\"><li><strong>Tx-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>PduR_CanTpCopyTxData()</code>: Callback von CanTp an PduR zum sequentiellen Kopieren von Tx-Daten in TP-Frames.\n</li><li><code>PduR_CanTpTxConfirmation()</code>: Abschluss-Callback von CanTp an PduR nach erfolgreicher oder fehlgeschlagener N-SDU-Transmission.\n</li></ul>\n</li><li><strong>Rx-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>PduR_CanTpStartOfReception()</code>: Initialer Callback bei Eintreffen eines Single Frame (SF) oder First Frame (FF) zur Pufferbereitstellung/-reservierung.\n</li><li><code>PduR_CanTpCopyRxData()</code>: Callback zum fortlaufenden Schreiben empfangener Consecutive Frames (CF) in den PduR-/Upper-Layer-Puffer.\n</li><li><code>PduR_CanTpRxIndication()</code>: Terminaler Callback zur Signalisierung der vollständigen oder abgebrochenen N-SDU-Rezeption.\n</li></ul>\n</li></ul>\n</li><li><strong>Rückgabewerte / Guards:</strong>\n<ul class=\"fig-list\"><li><code>BUFREQ_OK</code>: Bestätigung des PduR/Upper-Layers über ausreichenden und gültig referenzierten Speicher.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit Buffer Lifecycle</h5>\n<ol class=\"fig-list\"><li><strong>Initialzustand:</strong> <code>UNLOCK</code>.\n</li><li><strong>Transition <code>UNLOCK -&gt; LOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Aufruf von <code>PduR_CanTpCopyTxData()</code> durch CanTp.\n</li><li><strong>Guard:</strong> Rückgabewert der oberen Schicht ist <code>BUFREQ_OK</code>.\n</li><li><strong>Wirkung:</strong> Sobald CanTp das erste Byte/Segment anfordert und der PduR positiv quittiert, wird der Tx-Puffer verriegelt.\n</li></ul>\n</li><li><strong>Transition <code>LOCK -&gt; UNLOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpTxConfirmation()</code> auf (nach Versenden des letzten Segments inklusive Link-Layer-Confirmation oder bei Übertragungsabbruch via Timeout/N_As/N_Bs).\n</li><li><strong>Wirkung:</strong> Pufferfreigabe an den Eigentümer.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Receiving Buffer Lifecycle</h5>\n<ol class=\"fig-list\"><li><strong>Initialzustand:</strong> <code>UNLOCK</code>.\n</li><li><strong>Transition <code>UNLOCK -&gt; LOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger / Guard:</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>PduR_CanTpStartOfReception()</code> mit Rückgabe <code>BUFREQ_OK</code> (Standardpfad für SF/FF), <strong>ODER</strong>\n</li><li>Aufruf von <code>PduR_CanTpCopyRxData()</code> mit Rückgabe <code>BUFREQ_OK</code> (z. B. dynamische Pufferzuweisung oder verzögerte Bereitstellung).\n</li></ul>\n</li><li><strong>Wirkung:</strong> Der zugewiesene Empfangsbereich wird gelockt und darf bis zur finalen Indikation nicht überschrieben oder deallokiert werden.\n</li></ul>\n</li><li><strong>Transition <code>LOCK -&gt; UNLOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpRxIndication()</code> auf (erfolgreicher Empfang aller CFs oder Abbruch durch Timeout N_Ar/N_Cr/FC-Fehler).\n</li><li><strong>Wirkung:</strong> Puffer wird an DCM/COM zur Weiterverarbeitung übergeben und entsperrt.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zero-Copy / No-Internal-Buffering-Prinzip:</strong> CanTp allokiert im AUTOSAR-Standard keinen eigenen linearen N-SDU-Vollpuffer. Das Modul verlässt sich strikt auf die Puffer der oberen Schichten.\n</li><li><strong>Vertrag für Stack- und Treiber-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Zwischen <code>BUFREQ_OK</code> und <code>TxConfirmation</code> bzw. <code>RxIndication</code> darf die obere Schicht (insb. DCM für Diagnose-Nachrichten) den Pufferzeiger weder umbiegen, deallokieren noch den Inhalt mutieren.\n</li><li>Ein verfrühter Zugriff führt unmittelbar zu Datenkorruption bei aktiven CAN-Transceiver-Übertragungen (z. B. CAN-FD mit bis zu 64 Byte Payload pro Frame).\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Bricht eine Übertragung vorzeitig ab (z. B. N_Ar/N_Cs Timeout), <strong>muss</strong> CanTp zwingend <code>PduR_CanTpTxConfirmation()</code> bzw. <code>PduR_CanTpRxIndication()</code> mit dem Ergebnis <code>E_NOT_OK</code> aufrufen, da andernfalls ein permanenter Ressourcen-Lock (Memory Leak / Hang) in der oberen Schicht resultiert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-092694d2d37c3dac", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Zustandsautomat (<code>sm Buffer lock</code>) mit zwei orthogonalen, nebenläufigen Zustandsräumen (<em>Transmit Buffer</em> und <em>Receiving Buffer</em>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Schicht der Kommunikations-Dienste (<em>Communication Services</em>), Modul <strong>CanTp</strong> (CAN Transport Layer, ISO 15765-2) im Zusammenspiel mit dem <strong>PduR</strong> (PDU Router) und den oberen Schichten (DCM, COM).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Definition des Puffer-Lebenszyklus und der Puffer-Sperrsemantik (<em>Buffer Locking</em>) in den übergeordneten Modulen während segmentierter sowie unsegmentierter N-SDU-Übertragungen (Tx) und -Empfangsvorgänge (Rx), um Dateninkonsistenzen (Race Conditions, Buffer Overwrites) bei asynchroner Datenbereitstellung zu verhindern.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>CanTp:</strong> Transport-Schicht-Modul, das die Segmentierung/Reassemblierung ausführt und Callbacks an die obere Schicht absetzt bzw. Sendeaufträge entgegennimmt.\n</li><li><strong>PduR / Upper Layer (DCM / COM):</strong> Eigentümer der N-SDU-Puffer (<code>Transmit Buffer</code>, <code>Receiving Buffer</code>).\n</li></ul>\n</li><li><strong>Zustände (je Pufferinstanz):</strong>\n<ul class=\"fig-list\"><li><code>UNLOCK</code>: Puffer steht der übergeordneten Schicht zur freien Modifikation, Freigabe oder Neuzuweisung bereit.\n</li><li><code>LOCK</code>: Puffer ist für die Transportübertragung exklusiv an CanTp gebunden; Modifikationen durch die Applikation/obere Schicht sind unzulässig.\n</li></ul>\n</li><li><strong>Schnittstellen / API-Signaturen:</strong>\n<ul class=\"fig-list\"><li><strong>Tx-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>CanTp_Transmit()</code>: Synchroner Aufruf der übergeordneten Schicht (PduR) an CanTp zur Initiierung der N-SDU-Transmission.\n</li><li><code>PduR_CanTpTxConfirmation()</code>: Abschluss-Callback von CanTp an PduR nach erfolgreicher oder fehlgeschlagener N-SDU-Transmission.\n</li></ul>\n</li><li><strong>Rx-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>PduR_CanTpStartOfReception()</code>: Initialer Callback von CanTp an PduR bei Eintreffen eines Single Frame (SF) oder First Frame (FF) zur Pufferreservierung.\n</li><li><code>PduR_CanTpRxIndication()</code>: Terminaler Callback von CanTp an PduR zur Signalisierung der vollständigen oder abgebrochenen N-SDU-Rezeption.\n</li></ul>\n</li></ul>\n</li><li><strong>Rückgabewerte / Guards:</strong>\n<ul class=\"fig-list\"><li><code>E_OK</code>: Bestätigung von CanTp bei erfolgreicher Annahme des Sendeauftrags via <code>CanTp_Transmit()</code>.\n</li><li><code>BUFREQ_OK</code>: Bestätigung des PduR/Upper-Layers über ausreichenden und gültig referenzierten Speicher bei <code>PduR_CanTpStartOfReception()</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit Buffer Lifecycle</h5>\n<ol class=\"fig-list\"><li><strong>Initialzustand:</strong> <code>UNLOCK</code>.\n</li><li><strong>Transition <code>UNLOCK -&gt; LOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Aufruf von <code>CanTp_Transmit()</code> durch die übergeordnete Schicht (PduR).\n</li><li><strong>Guard:</strong> Rückgabewert ist <code>E_OK</code>.\n</li><li><strong>Wirkung:</strong> Sobald CanTp den Sendeauftrag mit <code>E_OK</code> quittiert, wird der Tx-Puffer verriegelt. Die obere Schicht darf die Daten bis zum Abschluss der Übertragung nicht modifizieren oder freigeben.\n</li></ul>\n</li><li><strong>Transition <code>LOCK -&gt; UNLOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpTxConfirmation()</code> auf (nach Versenden des letzten Segments inklusive Link-Layer-Confirmation oder bei Übertragungsabbruch via Timeout/Fehler).\n</li><li><strong>Wirkung:</strong> Puffer wird an den Eigentümer freigegeben und wechselt zurück nach <code>UNLOCK</code>.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Receiving Buffer Lifecycle</h5>\n<ol class=\"fig-list\"><li><strong>Initialzustand:</strong> <code>UNLOCK</code>.\n</li><li><strong>Transition <code>UNLOCK -&gt; LOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpStartOfReception()</code> bei Empfang eines SF oder FF auf.\n</li><li><strong>Guard:</strong> Rückgabewert der oberen Schicht ist <code>BUFREQ_OK</code>.\n</li><li><strong>Wirkung:</strong> Der zugewiesene Empfangsbereich wird gelockt; ein späteres Überschreiben oder Umbiegen durch die obere Schicht ist bis zur finalen Indikation unzulässig.\n</li></ul>\n</li><li><strong>Transition <code>LOCK -&gt; UNLOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpRxIndication()</code> auf (vollständiger Empfang aller Segmente oder Rezeptionsabbruch durch Timeout/Protokollfehler).\n</li><li><strong>Wirkung:</strong> Pufferfreigabe und Übergabe an die obere Schicht (DCM/COM); Rückkehr in den Zustand <code>UNLOCK</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zero-Copy / No-Internal-Buffering-Prinzip:</strong> CanTp allokiert keinen eigenen linearen N-SDU-Vollpuffer, sondern greift direkt auf die von der oberen Schicht bereitgestellten Puffer zu.\n</li><li><strong>Vertrag für Stack- und Treiber-Entwickler:</strong>\n<ul class=\"fig-list\"><li><strong>Tx-Sperrzeitraum:</strong> Die Sperre des Transmit Buffers beginnt unmittelbar mit der erfolgreichen Rückgabe (<code>E_OK</code>) von <code>CanTp_Transmit()</code> und endet erst mit dem Aufruf von <code>PduR_CanTpTxConfirmation()</code>. Innerhalb dieses Intervalls darf der Puffer nicht verändert oder reallokiert werden.\n</li><li><strong>Rx-Sperrzeitraum:</strong> Der Empfangspuffer ist ab dem positiven Quittieren (<code>BUFREQ_OK</code>) von <code>PduR_CanTpStartOfReception()</code> bis zur Ausführung von <code>PduR_CanTpRxIndication()</code> exklusiv für CanTp reserviert.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Bricht eine Transaktion vorzeitig ab (z. B. N_As-, N_Bs-, N_Ar- oder N_Cr-Timeout), <strong>muss</strong> CanTp zwingend <code>PduR_CanTpTxConfirmation()</code> bzw. <code>PduR_CanTpRxIndication()</code> mit dem Ergebnis <code>E_NOT_OK</code> aufrufen, um verwaiste Locks (Resource Leaks) in der oberen Schicht zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5b2f07c0c5efbd5c", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Zustandsautomat (<code>sm Buffer lock</code>) mit zwei orthogonalen, nebenläufigen Zustandsräumen (<em>Transmit Buffer</em> und <em>Receiving Buffer</em>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Schicht der Kommunikations-Dienste (<em>Communication Services</em>), Modul <strong>CanTp</strong> (CAN Transport Layer, ISO 15765-2) im Zusammenspiel mit dem <strong>PduR</strong> (PDU Router) und den oberen Schichten (DCM, COM).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Definition des Puffer-Lebenszyklus und der Puffer-Sperrsemantik (<em>Buffer Locking</em>) in den übergeordneten Modulen während segmentierter sowie unsegmentierter N-SDU-Übertragungen (Tx) und -Empfangsvorgänge (Rx), um Dateninkonsistenzen (Race Conditions, Buffer Overwrites) bei asynchroner Datenbereitstellung zu verhindern.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>CanTp:</strong> Transport-Schicht-Modul, das die Segmentierung/Reassemblierung ausführt und Callbacks an die obere Schicht absetzt bzw. Sendeaufträge entgegennimmt.\n</li><li><strong>PduR / Upper Layer (DCM / COM):</strong> Eigentümer der N-SDU-Puffer (<code>Transmit Buffer</code>, <code>Receiving Buffer</code>).\n</li></ul>\n</li><li><strong>Zustände (je Pufferinstanz):</strong>\n<ul class=\"fig-list\"><li><code>UNLOCK</code>: Puffer steht der übergeordneten Schicht zur freien Modifikation, Freigabe oder Neuzuweisung bereit.\n</li><li><code>LOCK</code>: Puffer ist für die Transportübertragung exklusiv an CanTp gebunden; Modifikationen durch die Applikation/obere Schicht sind unzulässig.\n</li></ul>\n</li><li><strong>Schnittstellen / API-Signaturen:</strong>\n<ul class=\"fig-list\"><li><strong>Tx-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>CanTp_Transmit()</code>: Synchroner Aufruf der übergeordneten Schicht (PduR) an CanTp zur Initiierung der N-SDU-Transmission.\n</li><li><code>PduR_CanTpTxConfirmation()</code>: Abschluss-Callback von CanTp an PduR nach erfolgreicher oder fehlgeschlagener N-SDU-Transmission.\n</li></ul>\n</li><li><strong>Rx-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>PduR_CanTpStartOfReception()</code>: Initialer Callback von CanTp an PduR bei Eintreffen eines Single Frame (SF) oder First Frame (FF) zur Pufferreservierung.\n</li><li><code>PduR_CanTpRxIndication()</code>: Terminaler Callback von CanTp an PduR zur Signalisierung der vollständigen oder abgebrochenen N-SDU-Rezeption.\n</li></ul>\n</li></ul>\n</li><li><strong>Rückgabewerte / Guards:</strong>\n<ul class=\"fig-list\"><li><code>E_OK</code>: Bestätigung von CanTp bei erfolgreicher Annahme des Sendeauftrags via <code>CanTp_Transmit()</code>.\n</li><li><code>BUFREQ_OK</code>: Bestätigung des PduR/Upper-Layers über ausreichenden und gültig referenzierten Speicher bei <code>PduR_CanTpStartOfReception()</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit Buffer Lifecycle</h5>\n<ol class=\"fig-list\"><li><strong>Initialzustand:</strong> <code>UNLOCK</code>.\n</li><li><strong>Transition <code>UNLOCK -&gt; LOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Aufruf von <code>CanTp_Transmit()</code> durch die übergeordnete Schicht (PduR).\n</li><li><strong>Guard:</strong> Rückgabewert ist <code>E_OK</code>.\n</li><li><strong>Wirkung:</strong> Sobald CanTp den Sendeauftrag mit <code>E_OK</code> quittiert, wird der Tx-Puffer verriegelt. Die obere Schicht darf die Daten bis zum Abschluss der Übertragung nicht modifizieren oder freigeben.\n</li></ul>\n</li><li><strong>Transition <code>LOCK -&gt; UNLOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpTxConfirmation()</code> auf (nach Versenden des letzten Segments inklusive Link-Layer-Confirmation oder bei Übertragungsabbruch via Timeout/Fehler).\n</li><li><strong>Wirkung:</strong> Puffer wird an den Eigentümer freigegeben und wechselt zurück nach <code>UNLOCK</code>.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Receiving Buffer Lifecycle</h5>\n<ol class=\"fig-list\"><li><strong>Initialzustand:</strong> <code>UNLOCK</code>.\n</li><li><strong>Transition <code>UNLOCK -&gt; LOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpStartOfReception()</code> bei Empfang eines SF oder FF auf.\n</li><li><strong>Guard:</strong> Rückgabewert der oberen Schicht ist <code>BUFREQ_OK</code>.\n</li><li><strong>Wirkung:</strong> Der zugewiesene Empfangsbereich wird gelockt; ein späteres Überschreiben oder Umbiegen durch die obere Schicht ist bis zur finalen Indikation unzulässig.\n</li></ul>\n</li><li><strong>Transition <code>LOCK -&gt; UNLOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpRxIndication()</code> auf (vollständiger Empfang aller Segmente oder Rezeptionsabbruch durch Timeout/Protokollfehler).\n</li><li><strong>Wirkung:</strong> Pufferfreigabe und Übergabe an die obere Schicht (DCM/COM); Rückkehr in den Zustand <code>UNLOCK</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zero-Copy / No-Internal-Buffering-Prinzip:</strong> CanTp allokiert keinen eigenen linearen N-SDU-Vollpuffer, sondern greift direkt auf die von der oberen Schicht bereitgestellten Puffer zu.\n</li><li><strong>Vertrag für Stack- und Treiber-Entwickler:</strong>\n<ul class=\"fig-list\"><li><strong>Tx-Sperrzeitraum:</strong> Die Sperre des Transmit Buffers beginnt unmittelbar mit der erfolgreichen Rückgabe (<code>E_OK</code>) von <code>CanTp_Transmit()</code> und endet erst mit dem Aufruf von <code>PduR_CanTpTxConfirmation()</code>. Innerhalb dieses Intervalls darf der Puffer nicht verändert oder reallokiert werden.\n</li><li><strong>Rx-Sperrzeitraum:</strong> Der Empfangspuffer ist ab dem positiven Quittieren (<code>BUFREQ_OK</code>) von <code>PduR_CanTpStartOfReception()</code> bis zur Ausführung von <code>PduR_CanTpRxIndication()</code> exklusiv für CanTp reserviert.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Bricht eine Transaktion vorzeitig ab (z. B. N_As-, N_Bs-, N_Ar- oder N_Cr-Timeout), <strong>muss</strong> CanTp zwingend <code>PduR_CanTpTxConfirmation()</code> bzw. <code>PduR_CanTpRxIndication()</code> mit dem Ergebnis <code>E_NOT_OK</code> aufrufen, um verwaiste Locks (Resource Leaks) in der oberen Schicht zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-94d13fbb4d265ccf", "releases": ["R21-11", "R22-11", "R24-11", "R25-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Zustandsautomat (<code>sm Buffer lock</code>) mit zwei orthogonalen, nebenläufigen Zustandsräumen (<em>Transmit Buffer</em> und <em>Receiving Buffer</em>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Schicht der Kommunikations-Dienste (<em>Communication Services</em>), Modul <strong>CanTp</strong> (CAN Transport Layer, ISO 15765-2) im Zusammenspiel mit dem <strong>PduR</strong> (PDU Router) und den oberen Schichten (DCM, COM).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Definition des Puffer-Lebenszyklus und der Puffer-Sperrsemantik (<em>Buffer Locking</em>) in den übergeordneten Modulen während segmentierter sowie unsegmentierter N-SDU-Übertragungen (Tx) und -Empfangsvorgänge (Rx), um Dateninkonsistenzen (Race Conditions, Buffer Overwrites) bei asynchroner Datenbereitstellung zu verhindern.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>CanTp:</strong> Transport-Schicht-Modul, das die Segmentierung/Reassemblierung ausführt und Callbacks an die obere Schicht absetzt bzw. Sendeaufträge entgegennimmt.\n</li><li><strong>PduR / Upper Layer (DCM / COM):</strong> Eigentümer der N-SDU-Puffer (<code>Transmit Buffer</code>, <code>Receiving Buffer</code>).\n</li></ul>\n</li><li><strong>Zustände (je Pufferinstanz):</strong>\n<ul class=\"fig-list\"><li><code>UNLOCK</code>: Puffer steht der übergeordneten Schicht zur freien Modifikation, Freigabe oder Neuzuweisung bereit.\n</li><li><code>LOCK</code>: Puffer ist für die Transportübertragung exklusiv an CanTp gebunden; Modifikationen durch die Applikation/obere Schicht sind unzulässig.\n</li></ul>\n</li><li><strong>Schnittstellen / API-Signaturen:</strong>\n<ul class=\"fig-list\"><li><strong>Tx-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>CanTp_Transmit()</code>: Synchroner Aufruf der übergeordneten Schicht (PduR) an CanTp zur Initiierung der N-SDU-Transmission.\n</li><li><code>PduR_CanTpTxConfirmation()</code>: Abschluss-Callback von CanTp an PduR nach erfolgreicher oder fehlgeschlagener N-SDU-Transmission.\n</li></ul>\n</li><li><strong>Rx-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>PduR_CanTpStartOfReception()</code>: Initialer Callback von CanTp an PduR bei Eintreffen eines Single Frame (SF) oder First Frame (FF) zur Pufferreservierung.\n</li><li><code>PduR_CanTpRxIndication()</code>: Terminaler Callback von CanTp an PduR zur Signalisierung der vollständigen oder abgebrochenen N-SDU-Rezeption.\n</li></ul>\n</li></ul>\n</li><li><strong>Rückgabewerte / Guards:</strong>\n<ul class=\"fig-list\"><li><code>E_OK</code>: Bestätigung von CanTp bei erfolgreicher Annahme des Sendeauftrags via <code>CanTp_Transmit()</code>.\n</li><li><code>BUFREQ_OK</code>: Bestätigung des PduR/Upper-Layers über ausreichenden und gültig referenzierten Speicher bei <code>PduR_CanTpStartOfReception()</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Transmit Buffer Lifecycle</h5>\n<ol class=\"fig-list\"><li><strong>Initialzustand:</strong> <code>UNLOCK</code>.\n</li><li><strong>Transition <code>UNLOCK -&gt; LOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Aufruf von <code>CanTp_Transmit()</code> durch die übergeordnete Schicht (PduR).\n</li><li><strong>Guard:</strong> Rückgabewert ist <code>E_OK</code>.\n</li><li><strong>Wirkung:</strong> Sobald CanTp den Sendeauftrag mit <code>E_OK</code> quittiert, wird der Tx-Puffer verriegelt. Die obere Schicht darf die Daten bis zum Abschluss der Übertragung nicht modifizieren oder freigeben.\n</li></ul>\n</li><li><strong>Transition <code>LOCK -&gt; UNLOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpTxConfirmation()</code> auf (nach Versenden des letzten Segments inklusive Link-Layer-Confirmation oder bei Übertragungsabbruch via Timeout/Fehler).\n</li><li><strong>Wirkung:</strong> Puffer wird an den Eigentümer freigegeben und wechselt zurück nach <code>UNLOCK</code>.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Receiving Buffer Lifecycle</h5>\n<ol class=\"fig-list\"><li><strong>Initialzustand:</strong> <code>UNLOCK</code>.\n</li><li><strong>Transition <code>UNLOCK -&gt; LOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpStartOfReception()</code> bei Empfang eines SF oder FF auf.\n</li><li><strong>Guard:</strong> Rückgabewert der oberen Schicht ist <code>BUFREQ_OK</code>.\n</li><li><strong>Wirkung:</strong> Der zugewiesene Empfangsbereich wird gelockt; ein späteres Überschreiben oder Umbiegen durch die obere Schicht ist bis zur finalen Indikation unzulässig.\n</li></ul>\n</li><li><strong>Transition <code>LOCK -&gt; UNLOCK</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> CanTp ruft <code>PduR_CanTpRxIndication()</code> auf (vollständiger Empfang aller Segmente oder Rezeptionsabbruch durch Timeout/Protokollfehler).\n</li><li><strong>Wirkung:</strong> Pufferfreigabe und Übergabe an die obere Schicht (DCM/COM); Rückkehr in den Zustand <code>UNLOCK</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zero-Copy / No-Internal-Buffering-Prinzip:</strong> CanTp allokiert keinen eigenen linearen N-SDU-Vollpuffer, sondern greift direkt auf die von der oberen Schicht bereitgestellten Puffer zu.\n</li><li><strong>Vertrag für Stack- und Treiber-Entwickler:</strong>\n<ul class=\"fig-list\"><li><strong>Tx-Sperrzeitraum:</strong> Die Sperre des Transmit Buffers beginnt unmittelbar mit der erfolgreichen Rückgabe (<code>E_OK</code>) von <code>CanTp_Transmit()</code> und endet erst mit dem Aufruf von <code>PduR_CanTpTxConfirmation()</code>. Innerhalb dieses Intervalls darf der Puffer nicht verändert oder reallokiert werden.\n</li><li><strong>Rx-Sperrzeitraum:</strong> Der Empfangspuffer ist ab dem positiven Quittieren (<code>BUFREQ_OK</code>) von <code>PduR_CanTpStartOfReception()</code> bis zur Ausführung von <code>PduR_CanTpRxIndication()</code> exklusiv für CanTp reserviert.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Bricht eine Transaktion vorzeitig ab (z. B. N_As-, N_Bs-, N_Ar- oder N_Cr-Timeout), <strong>muss</strong> CanTp zwingend <code>PduR_CanTpTxConfirmation()</code> bzw. <code>PduR_CanTpRxIndication()</code> mit dem Ergebnis <code>E_NOT_OK</code> aufrufen, um verwaiste Locks (Resource Leaks) in der oberen Schicht zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cb6553d7bc46b6e0", "to": "FIG-092694d2d37c3dac", "fr": "R4.0.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Transmit Buffer</code>: Die Transition <code>UNLOCK -&gt; LOCK</code> wird von <code>PduR_CanTpCopyTxData</code> (Guard <code>return = BUFREQ_OK</code>) auf den Funktionsaufruf <code>CanTp_Transmit()</code> (Guard <code>return = E_OK</code>) geändert. Die Sperrung des Sendepuffers erfolgt somit bereits bei der Sendeinitiierung statt erst beim Kopieren des ersten Segments.\n</li><li><code>Receiving Buffer</code>: An der Transition <code>UNLOCK -&gt; LOCK</code> entfällt der alternative Pfad <code>OR PduR_CanTpCopyRxData return = BUFREQ_OK</code> ersatzlos; der Empfangspuffer wird ausschließlich über <code>PduR_CanTpStartOfReception</code> (Guard <code>return = BUFREQ_OK</code>) gesperrt.\n</li></ul>"}, {"from": "FIG-092694d2d37c3dac", "to": "FIG-94d13fbb4d265ccf", "fr": "R4.2.2", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-94d13fbb4d265ccf", "to": "FIG-5b2f07c0c5efbd5c", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5b2f07c0c5efbd5c", "to": "FIG-94d13fbb4d265ccf", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
